const BulkCodeMappingsRequestSchema = z
  .object({
    project: z
      .union([z.int(), z.string()])
      .openapi({ description: 'The ID or slug of the project to configure.' }),
    repository: z.string().openapi({ description: 'The repository name as it appears in Sentry.' }),
    mappings: z
      .array(
        z
          .object({
            stack_root: z
              .string()
              .regex(/^[^\s'\"]+$/)
              .openapi({
                description:
                  'The path prefix to strip from matching stack frame filenames before adding sourceRoot.',
              }),
            source_root: z
              .string()
              .regex(/^[^\s'\"]+$/)
              .openapi({
                description:
                  'The repository path prefix that replaces stackRoot. For example, /app/pkg/file.py with stackRoot=/app/ and sourceRoot=src/ resolves to src/pkg/file.py.',
              }),
          })
          .openapi({ required: ['source_root', 'stack_root'] }),
      )
      .openapi({ description: 'One or more stack-root and source-root mappings (maximum 300).' }),
    provider: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Optional repository provider used to disambiguate or find the repository. If no matching Sentry repository exists, the repository is created after the provider confirms it exists.',
      }),
    default_branch: z
      .string()
      .regex(/^(^(?![\/]))([\w\.\/-]+)(?<![\/])$/)
      .exactOptional()
      .openapi({
        description: 'The repository branch to use; inferred from the integration when omitted.',
      }),
  })
  .openapi({
    description:
      'Allows parameters to be defined in snake case, but passed as camel case.\n\nErrors are output in camel case.',
    required: ['mappings', 'project', 'repository'],
  })
  .openapi('BulkCodeMappingsRequest')

