const CommitSerializerResponseSchema = z
  .array(
    z
      .object({
        id: z.string(),
        message: z.string().nullable(),
        dateCreated: z.iso.datetime({ offset: true }),
        pullRequest: z
          .object({
            id: z.string(),
            title: z.string().nullable(),
            message: z.string().nullable(),
            dateCreated: z.iso.datetime({ offset: true }),
            mergedAt: z.iso.datetime({ offset: true }).nullable(),
            status: z
              .union([
                z.literal('merged'),
                z.literal('open'),
                z.literal('closed'),
                z.literal('draft'),
                z.literal('unknown'),
                z.literal(null),
              ])
              .nullable(),
            repository: z
              .object({
                url: z.string().nullable().exactOptional(),
                provider: z.record(z.string(), z.string()).exactOptional(),
                status: z.string().exactOptional(),
                integrationId: z.string().nullable().exactOptional(),
                externalSlug: z.string().nullable().exactOptional(),
                externalId: z.string().nullable().exactOptional(),
                settings: z
                  .object({
                    enabledCodeReview: z.boolean(),
                    codeReviewTriggers: z.array(z.string()),
                  })
                  .nullable()
                  .exactOptional()
                  .openapi({ required: ['codeReviewTriggers', 'enabledCodeReview'] }),
                id: z.string(),
                name: z.string(),
                dateCreated: z.iso.datetime({ offset: true }),
              })
              .openapi({ required: ['dateCreated', 'id', 'name'] }),
            author: z.union([
              z
                .object({
                  identities: z
                    .array(
                      z
                        .object({
                          id: z.string(),
                          name: z.string(),
                          organization: z
                            .object({ slug: z.string(), name: z.string() })
                            .openapi({ required: ['name', 'slug'] }),
                          provider: z
                            .object({ id: z.string(), name: z.string() })
                            .openapi({ required: ['id', 'name'] }),
                          dateVerified: z.iso.datetime({ offset: true }),
                          dateSynced: z.iso.datetime({ offset: true }),
                        })
                        .openapi({
                          required: [
                            'dateSynced',
                            'dateVerified',
                            'id',
                            'name',
                            'organization',
                            'provider',
                          ],
                        }),
                    )
                    .exactOptional(),
                  avatar: z
                    .object({
                      avatarType: z.string().exactOptional(),
                      avatarUuid: z.string().nullable().exactOptional(),
                      avatarUrl: z.string().nullable().exactOptional(),
                    })
                    .exactOptional()
                    .openapi({ required: [] }),
                  authenticators: z.array(z.any()).exactOptional(),
                  canReset2fa: z.boolean().exactOptional(),
                  id: z.string(),
                  name: z.string(),
                  username: z.string(),
                  email: z.string(),
                  avatarUrl: z.string(),
                  isActive: z.boolean(),
                  isSuspended: z.boolean(),
                  hasPasswordAuth: z.boolean(),
                  isManaged: z.boolean(),
                  dateJoined: z.iso.datetime({ offset: true }),
                  lastLogin: z.iso.datetime({ offset: true }).nullable(),
                  has2fa: z.boolean(),
                  lastActive: z.iso.datetime({ offset: true }).nullable(),
                  isSuperuser: z.boolean(),
                  isStaff: z.boolean(),
                  experiments: z.record(z.string(), z.any()),
                  emails: z.array(
                    z
                      .object({ id: z.string(), email: z.string(), is_verified: z.boolean() })
                      .openapi({ required: ['email', 'id', 'is_verified'] }),
                  ),
                })
                .openapi({
                  required: [
                    'avatarUrl',
                    'dateJoined',
                    'email',
                    'emails',
                    'experiments',
                    'has2fa',
                    'hasPasswordAuth',
                    'id',
                    'isActive',
                    'isManaged',
                    'isStaff',
                    'isSuperuser',
                    'isSuspended',
                    'lastActive',
                    'lastLogin',
                    'name',
                    'username',
                  ],
                }),
              z
                .object({ name: z.string().nullable(), email: z.string() })
                .openapi({ required: ['email', 'name'] }),
            ]),
            externalUrl: z.string(),
          })
          .nullable()
          .openapi({
            required: [
              'author',
              'dateCreated',
              'externalUrl',
              'id',
              'mergedAt',
              'message',
              'repository',
              'status',
              'title',
            ],
          }),
        suspectCommitType: z.string(),
        repository: z
          .object({
            url: z.string().nullable().exactOptional(),
            provider: z.record(z.string(), z.string()).exactOptional(),
            status: z.string().exactOptional(),
            integrationId: z.string().nullable().exactOptional(),
            externalSlug: z.string().nullable().exactOptional(),
            externalId: z.string().nullable().exactOptional(),
            settings: z
              .object({ enabledCodeReview: z.boolean(), codeReviewTriggers: z.array(z.string()) })
              .nullable()
              .exactOptional()
              .openapi({ required: ['codeReviewTriggers', 'enabledCodeReview'] }),
            id: z.string(),
            name: z.string(),
            dateCreated: z.iso.datetime({ offset: true }),
          })
          .exactOptional()
          .openapi({ required: ['dateCreated', 'id', 'name'] }),
        author: z
          .union([
            z
              .object({
                identities: z
                  .array(
                    z
                      .object({
                        id: z.string(),
                        name: z.string(),
                        organization: z
                          .object({ slug: z.string(), name: z.string() })
                          .openapi({ required: ['name', 'slug'] }),
                        provider: z
                          .object({ id: z.string(), name: z.string() })
                          .openapi({ required: ['id', 'name'] }),
                        dateVerified: z.iso.datetime({ offset: true }),
                        dateSynced: z.iso.datetime({ offset: true }),
                      })
                      .openapi({
                        required: [
                          'dateSynced',
                          'dateVerified',
                          'id',
                          'name',
                          'organization',
                          'provider',
                        ],
                      }),
                  )
                  .exactOptional(),
                avatar: z
                  .object({
                    avatarType: z.string().exactOptional(),
                    avatarUuid: z.string().nullable().exactOptional(),
                    avatarUrl: z.string().nullable().exactOptional(),
                  })
                  .exactOptional()
                  .openapi({ required: [] }),
                authenticators: z.array(z.any()).exactOptional(),
                canReset2fa: z.boolean().exactOptional(),
                id: z.string(),
                name: z.string(),
                username: z.string(),
                email: z.string(),
                avatarUrl: z.string(),
                isActive: z.boolean(),
                isSuspended: z.boolean(),
                hasPasswordAuth: z.boolean(),
                isManaged: z.boolean(),
                dateJoined: z.iso.datetime({ offset: true }),
                lastLogin: z.iso.datetime({ offset: true }).nullable(),
                has2fa: z.boolean(),
                lastActive: z.iso.datetime({ offset: true }).nullable(),
                isSuperuser: z.boolean(),
                isStaff: z.boolean(),
                experiments: z.record(z.string(), z.any()),
                emails: z.array(
                  z
                    .object({ id: z.string(), email: z.string(), is_verified: z.boolean() })
                    .openapi({ required: ['email', 'id', 'is_verified'] }),
                ),
              })
              .openapi({
                required: [
                  'avatarUrl',
                  'dateJoined',
                  'email',
                  'emails',
                  'experiments',
                  'has2fa',
                  'hasPasswordAuth',
                  'id',
                  'isActive',
                  'isManaged',
                  'isStaff',
                  'isSuperuser',
                  'isSuspended',
                  'lastActive',
                  'lastLogin',
                  'name',
                  'username',
                ],
              }),
            z
              .object({ name: z.string().nullable(), email: z.string() })
              .openapi({ required: ['email', 'name'] }),
            z
              .object({})
              .openapi({
                description:
                  'The commit serializer emits ``{}`` for ``author`` when the commit has no\nmapped author, so the published schema must allow an empty object alongside a\npopulated ``Author``.',
              }),
          ])
          .exactOptional(),
      })
      .openapi({ required: ['dateCreated', 'id', 'message', 'pullRequest', 'suspectCommitType'] }),
  )
  .openapi('CommitSerializerResponse')

