const CreateOrganizationCodeMappingRequestSchema = z
  .object({
    repository_id: z
      .int()
      .openapi({ description: 'The ID of a repository belonging to the installed integration.' }),
    project_id: z
      .int()
      .openapi({ description: 'The ID of the project to associate with the code mapping.' }),
    stack_root: z
      .string()
      .regex(/^[^\s'\"]+$/)
      .openapi({ description: 'The path prefix to replace in stack trace filenames.' }),
    source_root: z
      .string()
      .regex(/^[^\s'\"]+$/)
      .openapi({
        description: 'The repository path prefix to substitute for the stack trace prefix.',
      }),
    integration_id: z
      .int()
      .openapi({
        description: 'The ID of the installed integration that provides the repository.',
      }),
    default_branch: z
      .string()
      .regex(/^(^(?![\/]))([\w\.\/-]+)(?<![\/])$/)
      .exactOptional()
      .openapi({
        description:
          'The default branch to use when resolving source files. May be empty for Perforce.',
      }),
  })
  .openapi({
    description:
      'Allows parameters to be defined in snake case, but passed as camel case.\n\nErrors are output in camel case.',
    required: ['integration_id', 'project_id', 'repository_id', 'source_root', 'stack_root'],
  })
  .openapi('CreateOrganizationCodeMappingRequest')

