const CustomInboundFilterSchema = z
  .object({
    id: z.string().openapi({ readOnly: true, description: 'The ID of the filter.' }),
    dataType: z
      .enum(['all', 'error', 'log', 'metric', 'span'])
      .openapi({
        description:
          'The data the filter matches against. `all` is the catch-all: it filters every data type Sentry ingests, including ones added later, and accepts only the conditions that every data type carries a field for.\n\n* `all`\n* `error`\n* `log`\n* `metric`\n* `span`',
      }),
    conditions: z
      .array(
        z
          .object({
            type: z
              .enum([
                'error_type',
                'error_message',
                'log_message',
                'metric_name',
                'release',
                'ip_address',
                'geo_country_code',
              ])
              .openapi({
                description:
                  'The field the condition matches against. Every `dataType` accepts `release` and `ip_address`. In addition, `error` accepts `error_type`, `error_message` and `geo_country_code`, `log` accepts `log_message`, and `metric` accepts `metric_name`. `span` and `all` accept no other types.\n\n* `error_type`\n* `error_message`\n* `log_message`\n* `metric_name`\n* `release`\n* `ip_address`\n* `geo_country_code`',
              }),
            operator: z
              .enum([
                'glob',
                'equals',
                'starts_with',
                'contains',
                'ends_with',
                'does_not_start_with',
                'does_not_contain',
                'does_not_end_with',
                'cidr',
                'not_cidr',
                'gt',
                'gte',
                'lt',
                'lte',
              ])
              .exactOptional()
              .openapi({
                description:
                  'How the field compares to `value`. `glob` matches the field against each value as a glob pattern. `equals`, `starts_with`, `contains` and `ends_with` match the field against each value case-insensitively, with every character read literally; `does_not_start_with`, `does_not_contain` and `does_not_end_with` match when no value does. `cidr` matches `ip_address` against each value as an address or a CIDR range, and `not_cidr` matches when no value does. `gt`, `gte`, `lt` and `lte` compare one value as a version and only apply to `release`.\n\n* `glob`\n* `equals`\n* `starts_with`\n* `contains`\n* `ends_with`\n* `does_not_start_with`\n* `does_not_contain`\n* `does_not_end_with`\n* `cidr`\n* `not_cidr`\n* `gt`\n* `gte`\n* `lt`\n* `lte`',
              }),
            value: z
              .array(z.string())
              .openapi({
                description:
                  'The values the field is compared to. The condition matches when any value matches, so multiple values act as OR; a negated operator matches when none does. A version comparison takes one release with a version such as `1.2.0` or `myapp@1.2.0`. A comparison with a package only applies to releases of that package.',
              }),
          })
          .openapi({ required: ['type', 'value'] }),
      )
      .openapi({
        description:
          "Conditions are combined with AND: an event must match every condition to be filtered out. There is no OR between conditions, so e.g. two release conditions can express a range (`gte 2.0` and `lt 4.0`). To broaden matching, widen a condition's values or add separate filters.",
      }),
    dateCreated: z.iso
      .datetime({ offset: true })
      .openapi({ readOnly: true, description: 'When the filter was created.' }),
    dateUpdated: z.iso
      .datetime({ offset: true })
      .openapi({ readOnly: true, description: 'When the filter was last changed.' }),
    legacyFilter: z
      .string()
      .nullable()
      .openapi({
        readOnly: true,
        description:
          'Set on a filter that holds one of the filter lists of the project settings, to the id its outcomes are reported under. Such a filter keeps its data type and its one condition: only the name, the active flag and the condition values can change, and deleting it empties the list.',
      }),
    name: z
      .string()
      .max(256)
      .nullable()
      .exactOptional()
      .openapi({ description: 'A human-readable label for the filter.' }),
    active: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether the filter drops matching data. An inactive filter is kept but ignored.',
      }),
  })
  .openapi({
    required: ['conditions', 'dataType', 'dateCreated', 'dateUpdated', 'id', 'legacyFilter'],
  })
  .openapi('CustomInboundFilter')

