const FiltersSchema = z
  .object({
    filetypes: z
      .array(
        z
          .enum([
            'pe',
            'pdb',
            'portablepdb',
            'mach_debug',
            'mach_code',
            'elf_debug',
            'elf_code',
            'wasm_debug',
            'wasm_code',
            'breakpad',
            'sourcebundle',
            'uuidmap',
            'bcsymbolmap',
            'il2cpp',
            'proguard',
            'dartsymbolmap',
          ])
          .openapi({
            description:
              '* `pe`\n* `pdb`\n* `portablepdb`\n* `mach_debug`\n* `mach_code`\n* `elf_debug`\n* `elf_code`\n* `wasm_debug`\n* `wasm_code`\n* `breakpad`\n* `sourcebundle`\n* `uuidmap`\n* `bcsymbolmap`\n* `il2cpp`\n* `proguard`\n* `dartsymbolmap`',
          }),
      )
      .exactOptional()
      .openapi({ description: 'The file types enabled for the source.' }),
    path_patterns: z
      .array(z.string())
      .exactOptional()
      .openapi({ description: 'The debug and code file paths enabled for the source.' }),
    requires_checksum: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether the source requires debug checksums.' }),
  })
  .openapi({
    description:
      'Filter settings for the source. This is optional for all sources.\n\n**`filetypes`** ***(list)*** - A list of file types that can be found on this source. If this is left empty, all file types will be enabled. The options are:\n- `pe` - Windows executable files\n- `pdb` - Windows debug files\n- `portablepdb` - .NET portable debug files\n- `mach_code` - MacOS executable files\n- `mach_debug` - MacOS debug files\n- `elf_code` - ELF executable files\n- `elf_debug` - ELF debug files\n- `wasm_code` - WASM executable files\n- `wasm_debug` - WASM debug files\n- `breakpad` - Breakpad symbol files\n- `sourcebundle` - Source code bundles\n- `uuidmap` - Apple UUID mapping files\n- `bcsymbolmap` - Apple bitcode symbol maps\n- `il2cpp` - Unity IL2CPP mapping files\n- `proguard` - ProGuard mapping files\n\n**`path_patterns`** ***(list)*** - A list of glob patterns to check against the debug and code file paths of debug files. Only files that match one of these patterns will be requested from the source. If this is left empty, no path-based filtering takes place.\n\n**`requires_checksum`** ***(boolean)*** - Whether this source requires a debug checksum to be sent with each request. Defaults to `false`.\n\n```json\n{\n    "filters": {\n        "filetypes": ["pe", "pdb", "portablepdb"],\n        "path_patterns": ["*ffmpeg*"]\n    }\n}\n```',
    required: [],
  })
  .openapi('Filters')

