const LayoutSchema = z
  .object({
    type: z
      .enum([
        'native',
        'symstore',
        'symstore_index2',
        'ssqp',
        'unified',
        'debuginfod',
        'slashsymbols',
        'nxsymstore',
      ])
      .openapi({
        description:
          "The source's layout type.\n\n* `native`\n* `symstore`\n* `symstore_index2`\n* `ssqp`\n* `unified`\n* `debuginfod`\n* `slashsymbols`\n* `nxsymstore`",
      }),
    casing: z
      .enum(['lowercase', 'uppercase', 'default'])
      .openapi({
        description: "The source's casing rules.\n\n* `lowercase`\n* `uppercase`\n* `default`",
      }),
  })
  .openapi({
    description:
      'Layout settings for the source. This is required for HTTP, GCS, and S3 sources.\n\n**`type`** ***(string)*** - The layout of the folder structure. The options are:\n- `native` - Platform-Specific (SymStore / GDB / LLVM)\n- `symstore` - Microsoft SymStore\n- `symstore_index2` - Microsoft SymStore (with index2.txt)\n- `ssqp` - Microsoft SSQP\n- `unified` - Unified Symbol Server Layout\n- `debuginfod` - debuginfod\n- `nxsymstore` - Nintendo NXSymStore\n\n**`casing`** ***(string)*** - The layout of the folder structure. The options are:\n- `default` - Default (mixed case)\n- `uppercase` - Uppercase\n- `lowercase` - Lowercase\n\n```json\n{\n    "layout": {\n        "type": "native"\n        "casing": "default"\n    }\n}\n```',
    required: ['casing', 'type'],
  })
  .openapi('Layout')

const LinkExternalIssueRequestSchema = z
  .object({
    externalIssue: z
      .string()
      .openapi({
        description:
          'The identifier or full URL of the existing external issue to link. URL support depends on the selected integration.',
      }),
    repo: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The repository containing the external issue, in owner/name format. Required by GitHub, GitHub Enterprise, and Bitbucket integrations.',
      }),
    comment: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'An optional comment to post to the external issue when linking, if supported by the integration.',
      }),
  })
  .openapi({ required: ['externalIssue'] })
  .openapi('LinkExternalIssueRequest')

