const OrganizationMemberRequestSchema = z
  .object({
    email: z
      .email()
      .max(75)
      .openapi({ description: 'The email address to send the invitation to.' }),
    role: z
      .enum(['member', 'admin', 'manager', 'owner'])
      .default('member')
      .exactOptional()
      .openapi({
        description:
          'Deprecated, use `orgRole`. The organization-level role to assign.\n\n* `member` - Member\n* `admin` - Admin\n* `manager` - Manager\n* `owner` - Owner',
        deprecated: true,
      }),
    orgRole: z
      .enum(['billing', 'member', 'manager', 'owner', 'admin'])
      .default('member')
      .exactOptional()
      .openapi({
        description:
          "The organization-level role of the new member. Roles include:\n\n* `billing` - Can manage payment and compliance details.\n* `member` - Can view and act on events, as well as view most other data within the organization.\n* `manager` - Has full management access to all teams and projects. Can also manage\n        the organization's membership.\n* `owner` - Has unrestricted access to the organization, its data, and its\n        settings. Can add, modify, and delete projects and members, as well as\n        make billing and plan changes.\n* `admin` - Can edit global integrations, manage projects, and add/remove teams.\n        They automatically assume the Team Admin role for teams they join.\n        Note: This role can no longer be assigned in Business and Enterprise plans. Use `TeamRoles` instead.\n        ",
      }),
    teams: z
      .array(z.any())
      .exactOptional()
      .openapi({
        description: 'Deprecated, use `teamRoles`. Slugs of teams to add the member to.',
        deprecated: true,
      }),
    teamRoles: z
      .array(z.record(z.string(), z.any()))
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The team and team-roles assigned to the member. Team roles can be either:\n        - `contributor` - Can view and act on issues. Depending on organization settings, they can also add team members.\n        - `admin` - Has full management access to their team's membership and projects.",
      }),
    sendInvite: z
      .boolean()
      .default(true)
      .exactOptional()
      .openapi({
        writeOnly: true,
        description:
          'Whether or not to send an invite notification through email. Defaults to True.',
      }),
    reinvite: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether or not to re-invite a user who has already been invited to the organization. Defaults to True.',
      }),
    regenerate: z
      .boolean()
      .exactOptional()
      .openapi({
        description: 'Reissue the invite token, invalidating any previously sent invite link.',
      }),
  })
  .openapi({ required: ['email'] })
  .openapi('OrganizationMemberRequest')

