export const deleteApi0OrganizationsOrganizationIdOrSlugPreprodartifactsSnapshotsSnapshotIdIndexRoute =
  createRoute({
    method: 'delete',
    path: '/api/0/organizations/{organization_id_or_slug}/preprodartifacts/snapshots/{snapshot_id}/',
    tags: ['Snapshots'],
    summary: 'Delete a Snapshot',
    description:
      'Delete a snapshot and all associated data (images, comparisons, metrics).\n\nThis is a permanent, irreversible operation. The snapshot and its images\nwill no longer be accessible after deletion.\n\nThis endpoint requires a bearer token with `project:write` access.',
    operationId: 'deleteOrganizationPreprodArtifactSnapshot',
    request: {
      params: z.object({
        organization_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'organization_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the organization the resource belongs to.',
              required: true,
            },
          }),
        snapshot_id: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'snapshot_id',
              schema: { type: 'string' },
              description: 'The ID of the snapshot to delete.',
              required: true,
            },
          }),
      }),
    },
    responses: {
      204: { description: 'No response body' },
      403: { description: 'Forbidden' },
      404: { description: 'Not Found' },
    },
    security: [{ auth_token: ['project:admin', 'project:releases'] }],
  })

