export const getApi0OrganizationsOrganizationIdOrSlugScimV2GroupsRoute = createRoute({
  method: 'get',
  path: '/api/0/organizations/{organization_id_or_slug}/scim/v2/Groups',
  tags: ['SCIM'],
  summary: "List an Organization's Paginated Teams",
  description:
    'Returns a paginated list of teams bound to a organization with a SCIM Groups GET Request.\n\nNote that the members field will only contain up to 10,000 members.',
  operationId: 'listOrganizationScimV2Groups',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
    }),
    query: z.object({
      startIndex: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'startIndex',
            schema: { type: 'integer', minimum: 1, default: 1 },
            description: 'SCIM 1-offset based index for pagination.',
            required: false,
          },
        }),
      count: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'count',
            schema: { type: 'integer', minimum: 0, default: 100 },
            description: 'The maximum number of results the query should return, maximum of 100.',
            required: false,
          },
        }),
      filter: z
        .string()
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'filter',
            schema: { type: 'string', minLength: 1 },
            description: 'A SCIM filter expression. The only operator currently supported is `eq`.',
            required: false,
          },
        }),
      excludedAttributes: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'excludedAttributes',
            schema: { type: 'array', items: { type: 'string' } },
            description:
              'Fields that should be left off of return values. Right now the only supported field for this query is members.',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              schemas: z.array(z.string()),
              totalResults: z.int(),
              startIndex: z.int(),
              itemsPerPage: z.int(),
              Resources: z.array(
                z
                  .object({
                    schemas: z.array(z.string()),
                    id: z.string(),
                    displayName: z.string(),
                    meta: z
                      .object({ resourceType: z.string() })
                      .openapi({ required: ['resourceType'] }),
                    members: z
                      .array(
                        z
                          .object({ value: z.string(), display: z.string() })
                          .openapi({ required: ['display', 'value'] }),
                      )
                      .exactOptional(),
                  })
                  .openapi({ required: ['displayName', 'id', 'meta', 'schemas'] }),
              ),
            })
            .openapi({
              required: ['Resources', 'itemsPerPage', 'schemas', 'startIndex', 'totalResults'],
            }),
          examples: {
            "ListAnOrgs'sPaginatedTeams": {
              summary: "List an orgs's paginated teams",
              value: {
                schemas: ['urn:ietf:params:scim:api:messages:2.0:ListResponse'],
                totalResults: 1,
                startIndex: 1,
                itemsPerPage: 1,
                Resources: [
                  {
                    schemas: ['urn:ietf:params:scim:schemas:core:2.0:Group'],
                    id: '23232',
                    displayName: 'test-scimv2',
                    members: [],
                    meta: { resourceType: 'Group' },
                  },
                ],
              },
            },
          },
        },
      },
    },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['team:admin', 'team:read', 'team:write'] }],
})

