export const deleteApi0ProjectsOrganizationIdOrSlugProjectIdOrSlugIndexRoute = createRoute({
  method: 'delete',
  path: '/api/0/projects/{organization_id_or_slug}/{project_id_or_slug}/',
  tags: ['Projects'],
  summary: 'Delete a Project',
  description:
    'Schedules a project for deletion.\n\nDeletion happens asynchronously and therefore is not immediate. However once deletion has\nbegun the state of a project changes and will be hidden from most public views.',
  operationId: 'deleteProject',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
      project_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'project_id_or_slug',
            schema: { type: 'string' },
            description:
              'The ID or slug of the project the resource belongs to. Project slugs are unique within each organization.',
            required: true,
          },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['project:admin'] }],
})

