export const getApi0ProjectsOrganizationIdOrSlugProjectIdOrSlugPreprodSnapshotsStatusCheckRulesIndexRoute =
  createRoute({
    method: 'get',
    path: '/api/0/projects/{organization_id_or_slug}/{project_id_or_slug}/preprod/snapshots/status-check-rules/',
    tags: ['Snapshots'],
    summary: 'Retrieve Snapshot status check rules for a project',
    description:
      'Retrieve the current Snapshot status check rules configured for a project.\n\nUse this endpoint when external CI needs to evaluate the same Snapshot\nchange-type rules that Sentry uses. The endpoint returns the current\nproject configuration, not a historical snapshot from when a build was\nprocessed.\n\nThe response includes whether status check enforcement is enabled and the\nSnapshot change types that fail the status check.\n\nThis endpoint requires a bearer token with `project:read` access. Project\ndistribution tokens are not supported.\n\nResponse notes:\n\n- `enabled: false` means status-check enforcement is disabled for the project.\n- `rules` contains one boolean per Snapshot change type.\n- `failOnAdded`, `failOnRemoved`, `failOnChanged`, and `failOnRenamed`\n  indicate which unapproved change types fail the status check.',
    operationId: 'getProjectPreprodSnapshotStatusCheckRules',
    request: {
      params: z.object({
        organization_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'organization_id_or_slug',
              schema: { type: 'string' },
              description: 'The ID or slug of the organization the resource belongs to.',
              required: true,
            },
          }),
        project_id_or_slug: z
          .string()
          .openapi({
            param: {
              in: 'path',
              name: 'project_id_or_slug',
              schema: { type: 'string' },
              description:
                'The ID or slug of the project the resource belongs to. Project slugs are unique within each organization.',
              required: true,
            },
          }),
      }),
    },
    responses: {
      200: {
        description: '',
        content: {
          'application/json': {
            schema: z
              .object({
                enabled: z.boolean(),
                rules: z
                  .object({
                    failOnAdded: z.boolean(),
                    failOnRemoved: z.boolean(),
                    failOnChanged: z.boolean(),
                    failOnRenamed: z.boolean(),
                  })
                  .openapi({
                    required: ['failOnAdded', 'failOnChanged', 'failOnRemoved', 'failOnRenamed'],
                  }),
              })
              .openapi({ required: ['enabled', 'rules'] }),
            examples: {
              ConfiguredSnapshotStatusCheckRules: {
                summary: 'Configured Snapshot Status Check Rules',
                value: {
                  enabled: true,
                  rules: {
                    failOnAdded: false,
                    failOnRemoved: true,
                    failOnChanged: true,
                    failOnRenamed: false,
                  },
                },
              },
            },
          },
        },
      },
      403: { description: 'Forbidden' },
      404: { description: 'Not Found' },
    },
    security: [{ auth_token: ['project:admin', 'project:read', 'project:write'] }],
  })

