export const getApi0ProjectsOrganizationIdOrSlugProjectIdOrSlugStatsIndexRoute = createRoute({
  method: 'get',
  path: '/api/0/projects/{organization_id_or_slug}/{project_id_or_slug}/stats/',
  tags: ['Projects'],
  summary: 'Retrieve Event Counts for a Project',
  description:
    "Return a set of points representing a normalized timestamp and the number of\nevents seen in the period.\n\nQuery ranges are limited to Sentry's configured time-series resolutions.\nThis endpoint may change in the future without notice.",
  operationId: 'listProjectStats',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'organization_id_or_slug',
            schema: { type: 'string' },
            description: 'The ID or slug of the organization the resource belongs to.',
            required: true,
          },
        }),
      project_id_or_slug: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'project_id_or_slug',
            schema: { type: 'string' },
            description:
              'The ID or slug of the project the resource belongs to. Project slugs are unique within each organization.',
            required: true,
          },
        }),
    }),
    query: z.object({
      stat: z
        .enum(['blacklisted', 'generated', 'received', 'rejected'])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'stat',
            schema: { type: 'string', enum: ['blacklisted', 'generated', 'received', 'rejected'] },
            description: 'The name of the stat to query. Defaults to `received`.',
            required: false,
          },
        }),
      since: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float64(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'since',
            schema: { type: 'number', format: 'double' },
            description: 'A UNIX timestamp (in seconds) that sets the start of the query range.',
            required: false,
          },
        }),
      until: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.float64(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'until',
            schema: { type: 'number', format: 'double' },
            description: 'A UNIX timestamp (in seconds) that sets the end of the query range.',
            required: false,
          },
        }),
      resolution: z
        .enum(['10s', '1d', '1h'])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'resolution',
            schema: { type: 'string', enum: ['10s', '1d', '1h'] },
            description: 'An explicit time series resolution.',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z.array(z.array(z.int())),
          examples: {
            ProjectEventCounts: {
              summary: 'Project event counts',
              value: [
                [1541455200, 1184],
                [1541458800, 1410],
                [1541462400, 1440],
                [1541466000, 1682],
                [1541469600, 1203],
                [1541473200, 497],
                [1541476800, 661],
                [1541480400, 1481],
                [1541484000, 678],
                [1541487600, 1857],
                [1541491200, 819],
                [1541494800, 1013],
                [1541498400, 1883],
                [1541502000, 1450],
                [1541505600, 1102],
                [1541509200, 1317],
                [1541512800, 1017],
                [1541516400, 813],
                [1541520000, 1189],
                [1541523600, 496],
                [1541527200, 1936],
                [1541530800, 1405],
                [1541534400, 617],
                [1541538000, 1533],
              ],
            },
          },
        },
      },
    },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['project:admin', 'project:read', 'project:write'] }],
})

