export const postApi0SentryAppInstallationsUuidExternalIssueActionsIndexRoute = createRoute({
  method: 'post',
  path: '/api/0/sentry-app-installations/{uuid}/external-issue-actions/',
  tags: ['Integration'],
  summary: 'Create or Link an External Issue Through a Sentry App',
  description:
    "**Experimental:** This API is under active development and may change.\n\nInvoke the installed app's issue-link callback and store the returned association.\nSubmit the app-specific form fields alongside `groupId`, `action`, and `uri`.\nThe installation UUID, form fields, and `uri` come from the organization's\n`issue-link` Sentry App components.\n\nFor `action=link`, the optional `expectedExternalIssueUrl` query parameter\nrequires an exact canonical `webUrl` match. An existing matching link is\nreturned with HTTP 200 without calling the App; a different link\nreturns 409. The callback must also return this URL before a new link is\nsaved. Callback effects cannot be rolled back if its response conflicts.\nA new association returns HTTP 201. Omitting the parameter preserves the\nApp's existing replacement behavior and HTTP 200 response.",
  operationId: 'executeSentryAppInstallationExternalIssueAction',
  request: {
    params: z.object({
      uuid: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'uuid',
            schema: { type: 'string' },
            description: 'The UUID of the Sentry App installation.',
            required: true,
          },
        }),
    }),
    query: z.object({
      expectedExternalIssueUrl: z
        .url()
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'expectedExternalIssueUrl',
            schema: { type: 'string', format: 'uri', minLength: 1 },
            description:
              'The exact canonical webUrl of the external issue to link. Only supported for action=link. An existing matching association is a no-op; a different association or callback URL returns 409 without replacing the link.',
            required: false,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .looseObject({
              groupId: z.string().openapi({ description: 'The numeric Sentry issue ID.' }),
              action: z
                .enum(['link', 'create'])
                .openapi({ description: 'The action to perform: `link` or `create`.' }),
              uri: z
                .string()
                .openapi({
                  description: "The relative callback URI from the app's issue-link form.",
                }),
            })
            .openapi({ required: ['action', 'groupId', 'uri'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z.string(),
              issueId: z.string(),
              serviceType: z.string(),
              displayName: z.string(),
              webUrl: z.string(),
            })
            .openapi({ required: ['displayName', 'id', 'issueId', 'serviceType', 'webUrl'] }),
        },
      },
    },
    201: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z.string(),
              issueId: z.string(),
              serviceType: z.string(),
              displayName: z.string(),
              webUrl: z.string(),
            })
            .openapi({ required: ['displayName', 'id', 'issueId', 'serviceType', 'webUrl'] }),
        },
      },
    },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
    409: { description: 'Conflict' },
  },
  security: [{ auth_token: ['event:admin', 'event:write'] }],
})

export const getApi0SentryAppInstallationsUuidExternalRequestsIndexRoute = createRoute({
  method: 'get',
  path: '/api/0/sentry-app-installations/{uuid}/external-requests/',
  tags: ['Integration'],
  summary: "Retrieve a Sentry App's Select Field Options",
  description:
    '**Experimental:** This API is under active development and may change.\n\nRequest select options from the installed app. Each choice contains its value followed by its label.',
  operationId: 'getSentryAppInstallationExternalRequestOptions',
  request: {
    params: z.object({
      uuid: z
        .string()
        .openapi({
          param: {
            in: 'path',
            name: 'uuid',
            schema: { type: 'string' },
            description: 'The UUID of the Sentry App installation.',
            required: true,
          },
        }),
    }),
    query: z.object({
      uri: z
        .string()
        .min(1)
        .openapi({
          param: {
            in: 'query',
            name: 'uri',
            schema: { type: 'string', minLength: 1 },
            description: "The relative URI of the select field's options callback.",
            required: true,
          },
        }),
      projectId: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'projectId',
            schema: { type: 'integer' },
            description: 'The Sentry project ID to include in the options request.',
            required: false,
          },
        }),
      query: z
        .string()
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'query',
            schema: { type: 'string', minLength: 1 },
            description: 'The search text for select options.',
            required: false,
          },
        }),
      dependentData: z
        .string()
        .min(1)
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'dependentData',
            schema: { type: 'string', minLength: 1 },
            description:
              'A JSON-encoded object containing the values of fields this select depends on.',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              choices: z.array(z.array(z.string())),
              defaultValue: z.string().exactOptional(),
            })
            .openapi({ required: ['choices'] }),
        },
      },
    },
    400: { description: 'Bad Request' },
    401: { description: 'Unauthorized' },
    403: { description: 'Forbidden' },
    404: { description: 'Not Found' },
  },
  security: [{ auth_token: ['org:admin', 'org:integrations', 'org:read', 'org:write'] }],
})

