export const deleteApi0ProjectsOrganizationIdOrSlugProjectIdOrSlugIssuesIndexRoute = createRoute({
  method: 'delete',
  path: '/api/0/projects/{organization_id_or_slug}/{project_id_or_slug}/issues/',
  tags: ['Events'],
  description:
    "Permanently remove the given issues. The list of issues to modify is given through the `id` query parameter.  It is repeated for each issue that should be removed.\n\nOnly queries by 'id' are accepted.\n\nIf any IDs are out of scope this operation will succeed without any data mutation.",
  operationId: 'Bulk Remove a List of Issues',
  request: {
    params: z.object({
      organization_id_or_slug: z
        .string()
        .openapi({
          param: {
            name: 'organization_id_or_slug',
            in: 'path',
            description: 'The ID or slug of the organization the issues belong to.',
            required: true,
            schema: { type: 'string' },
          },
        }),
      project_id_or_slug: z
        .string()
        .openapi({
          param: {
            name: 'project_id_or_slug',
            in: 'path',
            description: 'The ID or slug of the project the issues belong to.',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'id',
            in: 'query',
            description:
              'A list of IDs of the issues to be removed. This parameter shall be repeated for each issue, e.g. `?id=1&id=2&id=3`. If this parameter is not provided, it will attempt to remove the first 1000 issues.',
            schema: { type: 'integer' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    204: { description: 'Success' },
    403: { description: 'Forbidden' },
    404: { description: 'Project not found' },
  },
  security: [{ auth_token: ['event:admin'] }],
})

